package A_basic.model;
public class ATM { private final String atmId; private final String location; private double cashBalance; public ATM(String atmId, String location, double cashBalance) { this.atmId = atmId; this.location = location; this.cashBalance = cashBalance; } public void dispense(double amount) { cashBalance -= amount; } public void acceptCash(double amount) { cashBalance += amount; } @Override public String toString() { return "ATM{" + "atmId='" + atmId + "'" + ", location='" + location + "'" + ", cashBalance=" + cashBalance + '}'; } public String getAtmId() { return atmId; } public String getLocation() { return location; } public double getCashBalance() { return cashBalance; } }
